#pragma once
#include "system_research_common.hpp"
#include <map>
#include <set>
namespace kline { namespace system_research {
inline Report factor_replicating_gls(const Mat& x,const Vec& p){
    auto c=validate(x,1,2,64),d=x.size();require(d<=32&&c>d,"Invalid replication dimensions");auto m=c-d;parameters(p,m);require(m<=d,"Too many exposures");Mat S,B(m,Vec(d));for(std::size_t i=0;i<d;++i){S.emplace_back(x[i].begin(),x[i].begin()+d);for(std::size_t j=0;j<m;++j)B[j][i]=x[i][d+j];}Mat basis,W;for(auto&r:B){Vec v=r;double n=positive(std::sqrt(squared(v)));for(double&z:v)z/=n;for(int k=0;k<2;++k)for(auto&q:basis){double a=dot(q,v);for(std::size_t j=0;j<d;++j)v[j]-=a*q[j];}n=std::sqrt(squared(v));require(n>1e-10,"Dependent exposure constraints");for(double&z:v)z/=n;basis.push_back(v);W.push_back(solve_spd(S,r));}Mat G(m,Vec(m));for(std::size_t i=0;i<m;++i)for(std::size_t j=0;j<m;++j)G[i][j]=dot(B[i],W[j]);Vec nu=solve_spd(G,p),w(d,0);for(std::size_t j=0;j<m;++j)for(std::size_t i=0;i<d;++i)w[i]+=W[j][i]*nu[j];Vec g=mul(S,w),e=mul(B,w);double variance=dot(w,g);for(std::size_t i=0;i<d;++i)for(std::size_t j=0;j<m;++j)g[i]-=B[j][i]*nu[j];Report o{{"Asset","Weight","Variance"},{}};for(std::size_t j=0;j<m;++j)o.header.push_back("Exposure"+std::to_string(j+1));o.header.push_back("StationarityResidual");for(std::size_t i=0;i<d;++i){Vec r{double(i+1),w[i],variance};r.insert(r.end(),e.begin(),e.end());r.push_back(inf_norm(g));o.rows.push_back(r);}return o;
}

inline Report rolling_risk_scaling(const Mat& x,const Vec& p){
    auto d=validate(x,3,1,32);parameters(p,4+d);auto L=count(p[0],2,x.size()-1);double target=positive(p[1]),cap=positive(p[2]),fee=p[3];require(fee>=0&&fee<1&&double(x.size())*L*d<=5e7,"Invalid risk scaling controls");Vec base(p.begin()+4,p.end()),old(d,0),ret;require(l1(base)>0&&fee*cap*l1(base)<1,"Invalid base exposure");for(auto&r:x){for(double v:r)require(v>=-1,"Invalid return");ret.push_back(dot(base,r));}Report o{{"Period","Scale","ForecastVol","PortfolioReturn","NetReturn","Turnover","FeeFraction","NAV"},{}};for(std::size_t j=0;j<d;++j)o.header.push_back("Weight"+std::to_string(j+1));double nav=1;for(std::size_t t=L;t<x.size();++t){double m=0,v=0;for(std::size_t i=t-L;i<t;++i)m+=ret[i]/L;for(std::size_t i=t-L;i<t;++i)v+=std::pow(ret[i]-m,2)/(L-1);double s=std::sqrt(v),a=s>0?std::min(cap,target/s):cap;Vec w=base;for(double&z:w)z*=a;auto z=trade_step(old,w,x[t],fee);nav=positive(nav*(1+z.net));Vec r{double(t+1),a,s,z.gross,z.net,z.turnover,z.fee,nav};r.insert(r.end(),w.begin(),w.end());o.rows.push_back(r);old=z.drift;}return o;
}

inline Report minimum_variance_hedge(const Mat& x,const Vec& p){
    auto d=validate(x,3,3,34)-2;parameters(p,1);double lam=p[0];require(lam>=0,"Nonnegative ridge required");Vec m(d,0);double my=0,n=0;for(auto&r:x){require(r.back()==0||r.back()==1,"Binary train flag");if(r.back()){++n;my+=r[0];for(std::size_t j=0;j<d;++j)m[j]+=r[j+1];}}require(n>=2&&double(x.size())*d*d<=5e7,"Invalid hedge design");my/=n;for(double&v:m)v/=n;Mat S(d,Vec(d,0));Vec b(d,0);for(auto&r:x)if(r.back()){Vec z(d);for(std::size_t j=0;j<d;++j)z[j]=r[j+1]-m[j];add_outer(S,z,1/(n-1));for(std::size_t j=0;j<d;++j)b[j]+=z[j]*(r[0]-my)/(n-1);}for(std::size_t j=0;j<d;++j)S[j][j]+=lam;Vec h=solve_spd(S,b);Report o{{"Row","Train","Exposure","HedgedPnL"},{}};for(std::size_t j=0;j<d;++j)o.header.push_back("Hedge"+std::to_string(j+1));for(std::size_t i=0;i<x.size();++i){auto&r=x[i];Vec z(r.begin()+1,r.end()-1),v{double(i+1),r.back(),r[0],r[0]-dot(h,z)};v.insert(v.end(),h.begin(),h.end());o.rows.push_back(v);}return o;
}

inline Report scenario_tail_attribution(const Mat& x,const Vec& p){
    auto d=validate(x,2,2,33)-1;parameters(p,d+1);double alpha=p[0],tail=1-alpha;require(alpha>0&&alpha<1,"Invalid confidence");Vec w(p.begin()+1,p.end()),loss,prob;for(auto&r:x){prob.push_back(positive(r[0]));loss.push_back(dot(w,Vec(r.begin()+1,r.end())));}require(std::abs(sum(prob)-1)<=1e-10,"Probability sum must be one");std::vector<std::size_t> idx(x.size());std::iota(idx.begin(),idx.end(),0);std::stable_sort(idx.begin(),idx.end(),[&](auto a,auto b){return loss[a]<loss[b];});double mass=0,var=loss[idx.back()];for(auto i:idx){mass+=prob[i];if(mass+1e-14>=alpha){var=loss[i];break;}}double rem=tail,es=0;Vec c(d,0);for(std::size_t e=idx.size();e>0&&rem>1e-15;){std::size_t a=e-1;while(a>0&&loss[idx[a-1]]==loss[idx[e-1]])--a;double s=0;for(std::size_t k=a;k<e;++k)s+=prob[idx[k]];double take=std::min(rem,s);for(std::size_t k=a;k<e;++k){auto i=idx[k];double m=take*prob[i]/s;es+=m*loss[i]/tail;for(std::size_t j=0;j<d;++j)c[j]+=m*w[j]*x[i][j+1]/tail;}rem-=take;e=a;}Report o{{"Asset","Weight","VaR","ES","Contribution","SelectedMass","ConservationResidual"},{}};for(std::size_t j=0;j<d;++j)o.rows.push_back({double(j+1),w[j],var,es,c[j],tail-rem,std::abs(sum(c)-es)});return o;
}

inline Report cashflow_portfolio_unitization(const Mat& x,const Vec& p){
    validate(x,1,2,2);parameters(p,2);double nav=positive(p[0]),price=positive(p[1]),base=price,units=nav/price;Report o{{"Period","OpeningValue","ExternalFlow","Units","UnitPrice","ClosingValue","PeriodReturn","TWR","ConservationResidual"},{}};for(std::size_t i=0;i<x.size();++i){double opening=nav,F=x[i][0],r=x[i][1];require(r>-1,"Portfolio return must exceed -100 percent");double invested=positive(opening+F);units=positive(units+F/price);price=positive(price*(1+r));nav=positive(units*price);o.rows.push_back({double(i+1),opening,F,units,price,nav,r,price/base-1,std::abs(nav-invested*(1+r))});}return o;
}

inline Report portfolio_brinson_linked(const Mat& x,const Vec& p){
    validate(x,2,6,6);parameters(p,0);struct Period{double wp=0,wb=0,rp=0,rb=0;Mat rows;};std::map<double,Period> periods;std::set<std::pair<double,double>> seen;for(auto&r:x){require(r[0]==std::floor(r[0])&&r[1]==std::floor(r[1])&&r[2]>=0&&r[3]>=0&&r[4]>=-1&&r[5]>=-1,"Invalid attribution row");require(seen.insert({r[0],r[1]}).second,"Duplicate group period");auto&v=periods[r[0]];v.wp+=r[2];v.wb+=r[3];v.rp+=r[2]*r[4];v.rb+=r[3]*r[5];v.rows.push_back(r);}auto slope=[](double a,double b){double d=a-b;return d==0?1/positive(1+b):std::log1p(d/positive(1+b))/d;};double wp=1,wb=1;for(auto&kv:periods){auto&v=kv.second;require(std::abs(v.wp-1)<=1e-10&&std::abs(v.wb-1)<=1e-10,"Weights must sum to one");wp=positive(wp*(1+v.rp));wb=positive(wb*(1+v.rb));}double K=positive(slope(wp-1,wb-1)),active=wp-wb,s=0;Report o{{"Period","Group","Allocation","Selection","Interaction","LinkFactor","LinkedAllocation","LinkedSelection","LinkedInteraction","TotalActive","Residual"},{}};for(auto&kv:periods){auto&v=kv.second;double k=slope(v.rp,v.rb)/K;for(auto&r:v.rows){double a=(r[2]-r[3])*(r[5]-v.rb),b=r[3]*(r[4]-r[5]),c=(r[2]-r[3])*(r[4]-r[5]);s+=k*(a+b+c);o.rows.push_back({r[0],r[1],a,b,c,k,k*a,k*b,k*c,active,0});}}for(auto&r:o.rows)r.back()=std::abs(s-active);return o;
}
} }
